import{z as d,x as B,o,c as A,q as t,j as l,D as E,d as e,s as i,S as s,b as n}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"点分治","description":"","frontmatter":{"title":"点分治","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/centroid-decomposition.md","filePath":"cs/centroid-decomposition.md","lastUpdated":1791063341000}'),p={name:"cs/centroid-decomposition.md"};function c(m,a,h,u,D,_){const r=B("Mermaid");return o(),A("div",null,[a[2]||(a[2]=t('<h1 id="点分治" tabindex="-1">点分治 <a class="header-anchor" href="#点分治" aria-label="Permalink to &quot;点分治&quot;">​</a></h1><div class="epigraph"><p>树的重心子树不超过一半；以重心为根分治，路径统计变成「过当前根」与「落在子树」两支，层数 $O(\\log n)$。</p><footer>—— 据 Jordan 的树重心；分治范式见 CLRS 第 4 章；树上点分治为标准教材技法整理</footer></div><p>上一课<a href="/cs/heavy-light">重链剖分</a>把路径变成区间。有一类询问不是「路径聚合」，而是<strong>树上距离/路径计数</strong>：有多少对点距离为 \\(k\\)、路径权 \\(\\le K\\)。HLD 的线段树不直接数点对。缺口是点分治：选重心，统计过根的路径，再对每棵子树递归。不重写重链。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>树（无根）上，重心（centroid）满足：删掉后每棵连通块大小 \\(\\le n/2\\)。存在，且可在 \\(O(n)\\) 内找（两次 DFS 或一次换根）。以重心为根，任意路径要么过根，要么整段落在某子树。过根的用到根距离/权的集合做双指针或排序；子树递归。层数 \\(O(\\log n)\\)，每层扫边 \\(O(n)\\)，总 \\(O(n\\log n)\\) 再乘以层内统计代价。</p><p>缺口是这套分治树，不是再求 LCA。</p><h3 id="重心不是直径中点" tabindex="-1">重心不是直径中点 <a class="header-anchor" href="#重心不是直径中点" aria-label="Permalink to &quot;重心不是直径中点&quot;">​</a></h3><p>直径中点（或中心）与重心不同：一个管偏心距，一个管子树大小。<span class="marginnote">两者的直觉区别：中心管「离最远的人尽量近」（最坏情况最优，消防站选址），重心管「把人群切成尽量均等的两半」（规模平衡）。点分治要的是后者——每块不超过一半，递归深度才缩成对数；用直径中点来切，可能切出 \\(n-1\\) 的大块，深度退化成 \\(O(n)\\)。</span>点分治要的是大小平衡，保证递归深度对数。边分治把边当切，层数仍对数，实现更绕，本课点名。</p><p><span class="marginnote">Jordan 19 世纪已讨论树的重心。点分治是分治在树上的实例，主定理的形状：\\(T(n)= \\sum T(n_i)+O(n)\\)，\\(n_i\\le n/2\\)。后课 Kruskal 重构树用 MST 结构回答最大边查询，不是重心。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>找重心；标记已删（虚删）。收集子树到根的信息，容斥：全集统计减去同一子树内的（不过根）。递归未删子树。注意不要把过根路径算重：点对 \\((a,b)\\) 的 \\(lca\\) 在分治树上是某层重心。<span class="marginnote">容斥的数字实例：假设收集到 10 个点到根的距离，两两配出 45 个候选路径；其中若某棵子树贡献 4 个点，它们内部两两配出的 6 条路径根本不经过根，\\(45 - 6 = 39\\) 才是真过根的数。直接判断「这条路经不经过根」很难，「先全收再减」只用一次减法。</span></p>',11)),(o(),l(s,null,{default:E(()=>[i(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E6%89%BE%E9%87%8D%E5%BF%83%22%5D%20--%3E%20STAT%5B%22%E7%BB%9F%E8%AE%A1%E8%BF%87%E6%A0%B9%E8%B7%AF%E5%BE%84%22%5D%0A%20%20STAT%20--%3E%20REC%5B%22%E9%80%92%E5%BD%92%E5%AD%90%E6%A0%91%22%5D%0A%20%20REC%20--%3E%20C%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("p",null,"点分治树（centroid tree）深度 \\(O(\\log n)\\)，可当另一棵树预处理。",-1)),a[4]||(a[4]=n("h2",{id:"机制",tabindex:"-1"},[e("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=n("p",null,[e("每次切掉重心，块大小折半，递归树高对数。与"),n("a",{href:"/cs/divide-conquer"},"分治"),e("同型，平衡保证来自重心定义而非输入有序。容斥：过根 = 所有到根的配对减去同一子树内配对。哈希或排序做配对，复杂度随题。")],-1)),(o(),l(s,null,{default:E(()=>[i(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20ALL%5B%22%E4%BB%A5%E9%87%8D%E5%BF%83%20r%20%E6%94%B6%E9%9B%86%E6%89%80%E6%9C%89%E7%82%B9%E5%88%B0%20r%20%E7%9A%84%E8%B7%9D%E7%A6%BB%22%5D%20--%3E%20PAIR%5B%22%E4%B8%A4%E4%B8%A4%E9%85%8D%E5%AF%B9%EF%BC%9A%E5%80%99%E9%80%89%E8%B7%AF%E5%BE%84%E5%85%A8%E9%9B%86%22%5D%0A%20%20PAIR%20--%3E%20SUB%5B%22%E5%87%8F%E5%8E%BB%E5%90%8C%E4%B8%80%E5%AD%90%E6%A0%91%E5%86%85%E9%83%A8%E7%9A%84%E9%85%8D%E5%AF%B9%22%5D%0A%20%20SUB%20--%3E%20KEEP%5B%22%E5%89%A9%E4%B8%8B%20%3D%20%E7%9C%9F%E6%AD%A3%E7%BB%8F%E8%BF%87%20r%20%E7%9A%84%E8%B7%AF%E5%BE%84%22%5D%0A%20%20KEEP%20--%3E%20ANS%5B%22%E5%90%88%E5%B9%B6%E8%BF%9B%E7%AD%94%E6%A1%88%22%5D%0A%20%20KEEP%20--%3E%20REC%5B%22%E5%AF%B9%E6%AF%8F%E6%A3%B5%E5%AD%90%E6%A0%91%E9%80%92%E5%BD%92%E5%90%8C%E4%B8%80%E5%A5%97%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p>不要在带环图上找「重心」当点分治：先要块是树。点双连通上的点分治是另一层，不插入。</p><p><span class="marginnote">为什么平衡值得较真：\\(n = 10^6\\) 时，\\(O(n^2)\\) 是 \\(10^{12}\\) 次运算，单机要小时级；\\(O(n \\log n)\\) 约 \\(2 \\times 10^7\\) 次，毫秒级。重心把每层规模折半，正是「能算完」与「算不完」的分界线，不是理论洁癖。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写点分树套数据结构的全部模板变体。动态点分治（带修改）更重。后课默认：树上点对路径统计可用重心分治。下一课用 Kruskal 重构树回答「路径最大边 \\(\\le x\\)」一类查询。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>重心使子树 \\(\\le n/2\\)；路径过根或在子树。</li><li>每层 \\(O(n)\\)，深度 \\(O(\\log n)\\)。</li><li>管点对统计，不是路径区间修改。</li><li>出处：重心见经典图论；分治见 CLRS 第 4 章。</li></ul>',6))])}const g=d(p,[["render",c]]);export{T as __pageData,g as default};
